from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_CENT = Decimal('0.01')
_BRACKETS = ((Decimal('0.00'), Decimal('12450.00'), 19), (Decimal('12450.00'), Decimal('20200.00'), 24), (Decimal('20200.00'), Decimal('35200.00'), 30), (Decimal('35200.00'), Decimal('60000.00'), 37), (Decimal('60000.00'), Decimal('300000.00'), 45), (Decimal('300000.00'), None, 47))

def _parse_income(income):
    if not isinstance(income, str):
        raise ValueError('income must be a string')
    try:
        value = Decimal(income)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid income') from None
    if not value.is_finite() or value < 0:
        raise ValueError('invalid income')
    if value.as_tuple().exponent < -2:
        raise ValueError('invalid income')
    return value

def tax_breakdown(income):
    value = _parse_income(income)
    rows = []
    for lower, upper, rate in _BRACKETS:
        if value <= lower:
            break
        top = value if upper is None else min(value, upper)
        taxable = (top - lower).quantize(_CENT, rounding=ROUND_HALF_UP)
        if taxable > 0:
            tax = (taxable * Decimal(rate) / Decimal(100)).quantize(_CENT, rounding=ROUND_HALF_UP)
            rows.append({'from': lower.quantize(_CENT, rounding=ROUND_HALF_UP), 'to': None if upper is None else upper.quantize(_CENT, rounding=ROUND_HALF_UP), 'rate_percent': int(rate), 'taxable': taxable, 'tax': tax})
    return rows

def income_tax(income):
    total = sum((row['tax'] for row in tax_breakdown(income)), Decimal('0.00'))
    return total.quantize(_CENT, rounding=ROUND_HALF_UP)

def effective_rate_percent(income):
    value = _parse_income(income)
    if value == 0:
        return Decimal('0.0000')
    return (income_tax(income) / value * Decimal(100)).quantize(Decimal('0.0001'), rounding=ROUND_HALF_UP)

