from datetime import date
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP

_CENT = Decimal('0.01')
_DIGITS = '0123456789'

def _parse_date(value):
    if not isinstance(value, str):
        raise ValueError('invalid date')
    if len(value) != 10 or value[4] != '-' or value[7] != '-':
        raise ValueError('invalid date')
    parts = value[0:4] + value[5:7] + value[8:10]
    if any(ch not in _DIGITS for ch in parts):
        raise ValueError('invalid date')
    try:
        return date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        raise ValueError('invalid date') from None

def _parse_price(value):
    if not isinstance(value, str):
        raise ValueError('invalid monthly_price')
    try:
        price = Decimal(value)
    except (InvalidOperation, ValueError):
        raise ValueError('invalid monthly_price') from None
    if not price.is_finite() or price < 0:
        raise ValueError('invalid monthly_price')
    if price.as_tuple().exponent < -2:
        raise ValueError('invalid monthly_price')
    return price.quantize(_CENT, rounding=ROUND_HALF_UP)

def prorate_period(period_start, period_end, changes):
    start = _parse_date(period_start)
    end = _parse_date(period_end)
    if end <= start:
        raise ValueError('period_end must be after period_start')
    if not isinstance(changes, list) or len(changes) == 0:
        raise ValueError('changes must be a non-empty list')
    parsed = []
    seen = set()
    for entry in changes:
        if not isinstance(entry, dict) or set(entry.keys()) != {'date', 'monthly_price'}:
            raise ValueError('invalid change entry')
        change_date = _parse_date(entry['date'])
        price = _parse_price(entry['monthly_price'])
        if change_date in seen:
            raise ValueError('duplicate change date')
        seen.add(change_date)
        parsed.append((change_date, price))
    if min(item[0] for item in parsed) > start:
        raise ValueError('no plan covers period start')
    parsed.sort(key=lambda item: item[0])
    period_days = (end - start).days
    current_price = None
    for change_date, price in parsed:
        if change_date <= start:
            current_price = price
        else:
            break
    starts = [(start, current_price)]
    for change_date, price in parsed:
        if start < change_date < end:
            starts.append((change_date, price))
    merged = []
    for index, (seg_start, price) in enumerate(starts):
        seg_end = starts[index + 1][0] if index + 1 < len(starts) else end
        if merged and merged[-1][2] == price:
            merged[-1][1] = seg_end
        else:
            merged.append([seg_start, seg_end, price])
    segments = []
    total = Decimal('0.00')
    for seg_start, seg_end, price in merged:
        days = (seg_end - seg_start).days
        amount = (price * Decimal(days) / Decimal(period_days)).quantize(_CENT, rounding=ROUND_HALF_UP)
        total += amount
        segments.append({'from': seg_start.isoformat(), 'to': seg_end.isoformat(), 'days': days, 'monthly_price': price, 'amount': amount})
    return {'period_days': period_days, 'segments': segments, 'total': total.quantize(_CENT, rounding=ROUND_HALF_UP)}

