_ALLOWED = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

def _to_numeric(text):
    result = ''
    for ch in text:
        if '0' <= ch <= '9':
            result += ch
        else:
            result += str(ord(ch) - 55)
    return result

def rf_reference(base):
    if not isinstance(base, str):
        raise ValueError('base must be a string')
    normalized = base.replace(' ', '').upper()
    if len(normalized) < 1 or len(normalized) > 21:
        raise ValueError('invalid base')
    if any(ch not in _ALLOWED for ch in normalized):
        raise ValueError('invalid base')
    check = 98 - (int(_to_numeric(normalized + 'RF00')) % 97)
    return f'RF{check:02d}{normalized}'

def is_valid_rf_reference(text):
    if not isinstance(text, str):
        return False
    normalized = text.replace(' ', '').upper()
    if len(normalized) < 5 or len(normalized) > 25:
        return False
    if not normalized.startswith('RF'):
        return False
    if any(ch not in _ALLOWED for ch in normalized):
        return False
    if not ('0' <= normalized[2] <= '9' and '0' <= normalized[3] <= '9'):
        return False
    rearranged = normalized[4:] + normalized[:4]
    return int(_to_numeric(rearranged)) % 97 == 1
